import java.util.*;

class Main {
    static class Edge {
        int y, c, f, cost;
        Edge() {}
        Edge(int y, int c, int f, int cost) {
            this.y = y;
            this.c = c;
            this.f = f;
            this.cost = cost;
        }
    }

    static List<Edge> edges = new ArrayList<>();
    static final int MAXN = 14043;
    static List<Integer>[] graph = new ArrayList[MAXN];

    static long total_cost = 0;
    static long[] dist = new long[MAXN];
    static int[] parent = new int[MAXN];
    static int[] parent_edge = new int[MAXN];
    static int[] inq = new int[MAXN];

    static final long INF = (long)1e18;
    static int s = MAXN - 2;
    static int t = MAXN - 1;

    static int get_residual(int x) {
        return edges.get(x).c - edges.get(x).f;
    }

    static void update_flow() {
        Arrays.fill(dist, INF);
        Arrays.fill(parent, -1);
        Arrays.fill(parent_edge, -1);
        Arrays.fill(inq, 0);
        dist[s] = 0;
        Queue<Integer> q = new LinkedList<>();
        q.offer(s);
        inq[s] = 1;
        while (!q.isEmpty()) {
            int u = q.poll();
            inq[u] = 0;
            for (int e_idx : graph[u]) {
                if (get_residual(e_idx) == 0) continue;
                int cst = edges.get(e_idx).cost;
                int v = edges.get(e_idx).y;
                if (dist[v] > dist[u] + cst) {
                    dist[v] = dist[u] + cst;
                    parent[v] = u;
                    parent_edge[v] = e_idx;
                    if (inq[v] == 0) {
                        inq[v] = 1;
                        q.offer(v);
                    }
                }
            }
        }
        int cur = t;
        while (cur != s) {
            edges.get(parent_edge[cur]).f++;
            edges.get(parent_edge[cur] ^ 1).f--;
            cur = parent[cur];
        }
        total_cost += dist[t];
    }

    static void add_edge(int from, int to, int cap, int cst) {
        graph[from].add(edges.size());
        edges.add(new Edge(to, cap, 0, cst));
        graph[to].add(edges.size());
        edges.add(new Edge(from, 0, 0, -cst));
    }

    public static void main(String[] args) {
        for (int i = 0; i < MAXN; i++) {
            graph[i] = new ArrayList<>();
        }
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();
        int k = sc.nextInt();
        int c = sc.nextInt();
        int d = sc.nextInt();

        for (int i = 0; i < k; i++) {
            int x = sc.nextInt();
            add_edge(s, x, 1, 0);
        }

        int tt = 101;
        for (int i = 0; i < tt; i++) {
            add_edge(1 + i * n, t, k, i * c);
        }

        for (int i = 0; i < m; i++) {
            int x = sc.nextInt();
            int y = sc.nextInt();
            for (int j = 0; j < tt - 1; j++) {
                add_edge(x + j * n, y + j * n + n, 1, d * (j * 2 + 1));
                add_edge(y + j * n, x + j * n + n, 1, d * (j * 2 + 1));
            }
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < tt - 1; j++) {
                add_edge(i + j * n, i + j * n + n, k, 0);
            }
        }

        for (int i = 0; i < k; i++) {
            update_flow();
        }

        System.out.println(total_cost);
        sc.close();
    }
}
